import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

// Usage: node scripts/verify-trip-file-security-posture.mjs audit.psv amendments|quotes
// Parse the READ-ONLY SQL audit output generated by psql -qAt -F '|'.
const [, , file, fixture] = process.argv;
assert.ok(file && ['amendments','quotes'].includes(fixture),
  'usage: verify-trip-file-security-posture.mjs file amendments|quotes');
const rows = readFileSync(file, 'utf8').trim().split(/\r?\n/).map(line => line.split('|'));
const expected = [
  ['table','booking_change_requests'],
  ['table','booking_change_handoffs'],
  ['table','booking_change_handoff_events'],
  ['table','booking_change_source_evidence'],
  ['table','quote_version_snapshots'],
  ['function','create_booking_change_request'],
  ['function','decide_booking_change_request'],
  ['function','record_booking_change_handoff'],
  ['function','link_booking_change_source_evidence'],
  ['function','capture_quote_version_snapshot'],
];
assert.equal(rows.length,expected.length,'audit must report all ten planned objects');
const amendedObjects = new Set([
  'booking_change_requests',
  'booking_change_handoffs',
  'booking_change_handoff_events',
  'booking_change_source_evidence',
  'create_booking_change_request',
  'decide_booking_change_request',
  'record_booking_change_handoff',
  'link_booking_change_source_evidence',
]);
for (const [kind,name] of expected) {
  const matches = rows.filter(r => r[0]===kind && r[1]===name);
  assert.equal(matches.length,1,'missing or duplicate audit entry: '+kind+' '+name);
  const r=matches[0];
  assert.equal(r.length,9,'unexpected number of status fields for '+name);
  const shouldExist = fixture==='amendments' ? amendedObjects.has(name) : !amendedObjects.has(name);
  assert.equal(r[3],shouldExist?'t':'f','wrong installed state for '+name);
  assert.equal(r[2],shouldExist?'PASS':'BLOCK','unsafe or unexpectedly missing posture: '+name+'; '+r.join('|'));
  if (shouldExist) for (const flag of r.slice(4)) {
    assert.equal(flag,'t','failed security posture flag for '+name+': '+r.join('|'));
  }
}
console.log('Trip File '+fixture+' metadata/RLS/grant posture contract passed (disposable fixtures only).');
